    G.add_nodes_from(L)

    edges = []

    if e == []:
        for i in L:
            for j in L:
                if pyo.value(model.x[i, j]) > 0.5:
                    edges.append((i, j))
    else:
        edges = e

    G.add_edges_from(edges)

    pos = nx.circular_layout(G)

    nx.draw_networkx_edges(
        G, pos, edgelist=G.edges(), arrowstyle="->", arrowsize=20, width=2
    )
    labels = {node: "0" if node == "Depot" else node for node in G.nodes()}

    # Draw the graph
    nx.draw(G, pos, with_labels=True, labels=labels)
    plt.show()

# Subtour elimination (MTZ constraints)
model.u = pyo.Var(["A", "B", "C", "D"], domain=pyo.NonNegativeReals)

# Ensure values of u are sequential
for i in L:
    for j in L:
        if i != j and i != "Depot" and j != "Depot":
            model.cons.add(
                model.u[i] - model.u[j] + (len(L) - 1) * model.x[i, j] <= len(L) - 2
            )  # Connected cities have u values differ by 1

# Set a range for u variables
for i in L:
    if i != "Depot":
        model.cons.add(model.u[i] >= 1)
        model.cons.add(model.u[i] <= len(L) - 1)

results = pyo.SolverFactory("cbc").solve(model)
assert pyo.check_optimal_termination(results), (
    f"Solve failed: status={results.solver.status}, "
    f"termination={results.solver.termination_condition}"
)

